items.command:
/bin/zsh -lc "python3 - <<'PY'
from zipfile import ZipFile
import json
p='/Users/wangye/Desktop/贴纸/outputs/月下温泉-分割三号-完整贴纸素材包.zip'
with ZipFile(p) as z:
 prefix='月下温泉-分割三号-完整贴纸素材包/'
 for name in ['manifest.json','quality/summary.json','quality/validation.json','使用与组装指南.txt']:
  s=z.read(prefix+name).decode('utf-8-sig')
  if name=='manifest.json':
   d=json.loads(s)
   print(name,'keys:',list(d))
   for k,v in d.items():
    if isinstance(v,list): print(k,'count',len(v),'first',json.dumps(v[:2],ensure_ascii=False)[:9000])
    else: print(k,json.dumps(v,ensure_ascii=False)[:7000])
  else: print(name,s[:16000])
PY"

