 * include fixed foreground in the same global queue; never collapse a person into
 * one contiguous layer. For an exact custom queue use reorderRenderPartsDraft.
 */
export function reorderDraft(layout: GameLayout, orderedStickerIds?: readonly string[]): GameLayout {
  const draft = createLayoutDraft(layout);
  if (draft.renderOrder?.length) {
    if (orderedStickerIds) {
      throw new Error('Multipart scenes require an explicit render-part queue; use reorderRenderPartsDraft');
    }
    const stickers = new Map(draft.stickers.map(sticker => [sticker.stickerId, sticker]));
    for (const entry of draft.renderOrder) {
      if (entry.kind !== 'stickerPart') continue;
      const sticker = stickers.get(entry.stickerId ?? '');
      const parts = sticker?.renderParts;
      const part = parts?.find(candidate => candidate.partId === entry.partId);
      if (!sticker || !parts?.length || !part) throw new Error(`Invalid render queue part ${entry.partId}`);
      const sourceLayer = Math.min(...parts.map(candidate => candidate.layerIndex));
      entry.layerIndex = sticker.layerIndex + part.layerIndex - sourceLayer;
    }
    draft.renderOrder.sort((a, b) => a.layerIndex - b.layerIndex || a.placementOrder - b.placementOrder);
    synchronizeRenderOrders(draft);
    refreshPlayMetadata(draft);
    assertLayout(draft);
    return draft;
  }
  const ids = orderedStickerIds ? [...orderedStickerIds]
    : [...draft.stickers].sort((a, b) => a.layerIndex - b.layerIndex || a.placementOrder - b.placementOrder)
      .map(sticker => sticker.stickerId);
  const known = new Set(draft.stickers.map(sticker => sticker.stickerId));
  if (ids.length !== known.size || new Set(ids).size !== known.size || ids.some(id => !known.has(id))) {
    throw new Error('Reorder must include every sticker ID exactly once');
  }
  const rank = new Map(ids.map((id, index) => [id, (index + 1) * 10]));
  for (const sticker of draft.stickers) sticker.placementOrder = rank.get(sticker.stickerId)!;
  refreshPlayMetadata(draft);
  assertLayout(draft);
  return draft;
}

/** Stable identity for an entry in the single global part/fixed painter queue. */
export function renderEntryKey(entry: RenderQueueEntry): string {
  return entry.kind === 'fixed' ? `fixed:${entry.fixedId}` : `stickerPart:${entry.partId}`;
}

export function reorderRenderPartsDraft(layout: GameLayout, orderedEntryKeys: readonly string[]): GameLayout {
  const draft = createLayoutDraft(layout);
  if (!draft.renderOrder) throw new Error('Layout has no render-part queue');
  const entries = new Map(draft.renderOrder.map(entry => [renderEntryKey(entry), entry]));
  if (entries.size !== draft.renderOrder.length || orderedEntryKeys.length !== entries.size
    || new Set(orderedEntryKeys).size !== entries.size || orderedEntryKeys.some(key => !entries.has(key))) {
    throw new Error('Render-part reorder must include every part/fixed entry exactly once');
  }
  draft.renderOrder = orderedEntryKeys.map(key => entries.get(key)!);
  synchronizeRenderOrders(draft);
  refreshPlayMetadata(draft);
  assertLayout(draft);
  return draft;
}

function synchronizeRenderOrders(draft: GameLayout): void {
  const stickers = new Map(draft.stickers.map(sticker => [sticker.stickerId, sticker]));
  const fixed = new Map((draft.fixedLayers ?? []).map(layer => [layer.fixedId, layer]));
  for (const [index, entry] of (draft.renderOrder ?? []).entries()) {
    entry.placementOrder = (index + 1) * 10;
    entry.paintOrder = entry.placementOrder;
    if (entry.kind === 'fixed') {
      const layer = fixed.get(entry.fixedId ?? '');
      if (!layer) throw new Error(`Unknown fixed render layer ${entry.fixedId}`);
      layer.placementOrder = entry.placementOrder;
      layer.paintOrder = entry.placementOrder;
      layer.layerIndex = entry.layerIndex;
    } else {
      const part = stickers.get(entry.stickerId ?? '')?.renderParts?.find(candidate => candidate.partId === entry.partId);
      if (!part) throw new Error(`Unknown render part ${entry.partId}`);
      part.placementOrder = entry.placementOrder;
      part.paintOrder = entry.placementOrder;
      part.layerIndex = entry.layerIndex;
    }
  }
  for (const sticker of draft.stickers) {
    if (sticker.renderParts?.length) sticker.placementOrder = Math.min(...sticker.renderParts.map(part => part.placementOrder));
  if (errors.length || !object(value)) return errors;
  const draft = value as unknown as GameLayout;
  if (draft.sceneId !== source.sceneId) errors.push('sceneId differs from source');
  if (!object(draft.scene) || !object(source.scene)
    || ['width', 'height', 'baseAssetKey', 'referenceAssetKey'].some(k => field(draft.scene, k) !== field(source.scene, k))) errors.push('scene resources or dimensions changed');
  if (draft.stickers.length !== source.stickers.length) errors.push('logical sticker count changed');
  const sourceIds = new Set(source.stickers.map(s => s.stickerId));
  if (draft.stickers.some(s => !sourceIds.has(s.stickerId))) errors.push('unknown logical sticker ID');
  if (draft.geoBlocks.length !== source.geoBlocks.length || draft.geoBlocks.some(block =>
    !source.geoBlocks.some(original => original.blockId === block.blockId && original.blockOrder === block.blockOrder))) errors.push('geographic block identities/order changed');
  for (const original of source.stickers) {
    const row = draft.stickers.find(s => s.stickerId === original.stickerId);
    if (!row) { errors.push(`missing sticker ${original.stickerId}`); continue; }
    if (['file', 'assetKey', 'sourceSize', 'dependsOn'].some(k => !same(row[k], original[k]))) errors.push(`immutable sticker resource changed: ${row.stickerId}`);
    const parts = row.renderParts; const originalParts = original.renderParts ?? [];
    if (!Array.isArray(parts) || parts.length !== originalParts.length) { errors.push(`render parts missing: ${row.stickerId}`); continue; }
    if (parts.some(part => !object(part))) { errors.push(`malformed render part: ${row.stickerId}`); continue; }
    if (new Set(parts.map(p => p.partId)).size !== parts.length) errors.push(`duplicate part ID: ${row.stickerId}`);
    for (const sourcePart of originalParts) {
      const part = parts.find(p => p.partId === sourcePart.partId);
      if (!part || immutablePart.some(k => !same(part[k], sourcePart[k]))) errors.push(`immutable part resource changed: ${sourcePart.partId}`);
      else if (!order(part.placementOrder) || !Number.isSafeInteger(part.layerIndex)) errors.push(`invalid part painter order: ${sourcePart.partId}`);
    }
    if (parts.length && row.placementOrder !== Math.min(...parts.map(p => p.placementOrder))) errors.push(`logical order differs from first part: ${row.stickerId}`);
  }
  const fixed = draft.fixedLayers; const originalFixed = source.fixedLayers ?? [];
  if (!Array.isArray(fixed) || fixed.length !== originalFixed.length) errors.push('fixed foreground layers missing');
  else {
    if (fixed.some(row => !object(row))) { errors.push('malformed fixed foreground layer'); return errors; }
    if (new Set(fixed.map(f => f.fixedId)).size !== fixed.length) errors.push('duplicate fixed layer ID');
    for (const sourceFixed of originalFixed) {
      const row = fixed.find(f => f.fixedId === sourceFixed.fixedId);
      if (!row || immutableFixed.some(k => !same(row[k], sourceFixed[k]))) errors.push(`fixed resource changed: ${sourceFixed.fixedId}`);
    }
  }
  const render = draft.renderOrder; const sourceRender = source.renderOrder ?? [];
  if (!Array.isArray(render) || render.length !== sourceRender.length) errors.push('global render queue missing');
  else {
    if (render.some(row => !object(row))) { errors.push('malformed global render queue entry'); return errors; }
    const expected = new Set(sourceRender.map(key)); const actual = render.map(key);
    if (new Set(actual).size !== expected.size || actual.some(k => !expected.has(k))) errors.push('global render queue does not cover source entries exactly once');
    if (render.some(r => !order(r.placementOrder) || !Number.isSafeInteger(r.layerIndex))
      || new Set(render.map(r => r.placementOrder)).size !== render.length) errors.push('global painter orders must be unique positive integers');
    for (const row of render) {
      const owner: StickerPlacement | undefined = draft.stickers.find(s => s.stickerId === row.stickerId);
      const layer = row.kind === 'fixed' ? fixed?.find(f => f.fixedId === row.fixedId)
        : owner?.renderParts?.find(p => p.partId === row.partId);
      if (!layer || row.placementOrder !== layer.placementOrder || row.layerIndex !== layer.layerIndex) errors.push(`global queue differs from renderer layer: ${key(row)}`);
    }
  }
  return errors;
}

