def sha(path):
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        while chunk := handle.read(1024 * 1024):
            digest.update(chunk)
    return digest.hexdigest()


def write_json(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n")


def point(values):
    return {"x": values[0], "y": values[1]}


def size(values):
    return {"width": values[0], "height": values[1]}


def pixel_point(values):
    return point([round(v) for v in values])


def pixel_size(values):
    return size([round(v) for v in values])


def rect(bounds):
    x0, y0, x1, y1 = bounds
    return {"x": x0, "y": y0, "width": x1 - x0, "height": y1 - y0}


def union(rectangles):
    return [min(r[0] for r in rectangles), min(r[1] for r in rectangles),
            max(r[2] for r in rectangles), max(r[3] for r in rectangles)]


def alpha_stats(path):
    image = Image.open(path).convert("RGBA")
    alpha = image.getchannel("A")
    histogram = alpha.histogram()
    bbox = alpha.getbbox()
    return {
        "pixelSize": size(image.size), "alphaBounds": rect(bbox),
        "alphaNonzeroPixels": sum(histogram[1:]),
        "alphaThreshold32Pixels": sum(histogram[32:]),
        "alphaThreshold64Pixels": sum(histogram[64:]),
        "effectiveAlphaArea": round(sum(i * n for i, n in enumerate(histogram)) / 255, 4),
        "hasTransparentPixels": histogram[0] > 0,
    }


def level_for(asset, stats):
    if asset["category"] == "person":
        return "L2", "人物主体；人物完整单体在中件阶段放置"
    if asset["id"] in STRUCTURAL_IDS:
        return "L1", "明确家具支撑或场景结构主体；先建立摆放支撑"
    if stats["effectiveAlphaArea"] >= 7000:
        return "L1", "透明加权有效面积≥7000源像素的大件主体"
    bounds = stats["alphaBounds"]
    if (asset["category"] == "furniture" or stats["effectiveAlphaArea"] >= 1000
            or max(bounds["width"], bounds["height"]) >= 90):
        return "L2", "独立中件、小家具或长形主体；按透明有效面积与功能分类"
    return "L3", "透明加权有效面积<1000源像素且非结构/人物的精细小物"


def alpha_rle(path):
    image = Image.open(path).convert("RGBA")
    raw = image.getchannel("A").tobytes()
    runs, start = [], None
    for index, value in enumerate(raw):
        if value >= 32 and start is None:
            start = index
        elif value < 32 and start is not None:
            runs.extend((start, index - start))
            start = None
    if start is not None:
        runs.extend((start, len(raw) - start))
    return {"width": image.width, "height": image.height, "runs": runs,
            "pngSHA256": sha(path)}


def build(kit, output, zip_path):
    manifest_path = kit / "manifest.json"
