+// Prune superseded generated platform textures. The source resources/ PNGs
+// and approved high-resolution artwork stay intact for provenance.
+const prunePlatformPNG = (folder, active) => {
+  if (!fs.existsSync(folder)) return;
+  for (const name of fs.readdirSync(folder)) {
+    const filename = path.join(folder, name);
+    if (fs.statSync(filename).isDirectory()) prunePlatformPNG(filename, active);
+    else if (name.endsWith('.png') && !active.has(filename)) fs.unlinkSync(filename);
+  }
+};
